'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, view='planner', selectedDay='', period=1, toastTimer, filterTimer;
let upcomingData=null, upcomingError='', upcomingRequest=0, weekOffset=0, weekCount=1, upcomingTruck='', upcomingOperation='';
const filters={plate:'',loading:'',unloading:'',operation:'',status:''};
const names={board:'Fleet board',planner:'Daily planning',upcoming:'Upcoming planning',analytics:'Analytics',trailers:'Trailers',trucks:'Tractors',drivers:'Drivers & carriers',locations:'Saved locations',settings:'Settings & backup'};
const localParts = value => value ? String(value).slice(0,16) : '';
const dayOf = value => value ? String(value).slice(0,10) : '';
const addDays=(day,n)=>new Date(Date.parse(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
const formatDay=(day,full=false)=>new Intl.DateTimeFormat('en-GB',{weekday:full?'long':'short',day:'numeric',month:full?'long':'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));
const formatTime=value=>value?new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'}).format(new Date(value)):'—';
const formatDate=value=>value?formatDay(dayOf(value))+' · '+formatTime(value):'—';
const hours=value=>Number(value).toLocaleString('en-GB',{maximumFractionDigits:1})+' h';
const km=value=>value==null?'Unknown':Number(value).toLocaleString('en-GB',{maximumFractionDigits:1})+' km';
const getLocation=id=>state.locations.find(x=>x.id===Number(id));
const placeLabel=p=>p?`${p.city} · ${p.company} · ${p.postal_code}, ${p.country}`:'Unknown location';
const locationHtml=id=>{const p=getLocation(id);return p?`<div class="place"><strong>${esc(p.city)} <span class="muted">${esc(p.postal_code)}</span></strong><small>${esc(p.company)} · ${esc(p.country)}</small></div>`:'—';};
const badge=(value,kind='')=>`<span class="badge ${kind}">${esc(value)}</span>`;
const errorBox='<div class="form-error" role="alert"></div>';
const options=(items,value,label,empty='Choose…')=>`<option value="">${esc(empty)}</option>`+items.map(item=>`<option value="${item.id}" ${Number(value)===item.id?'selected':''}>${esc(label(item))}</option>`).join('');
const field=(label,name,value='',type='text',attrs='',hint='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</div>`;
const selectField=(label,name,body)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${body}</select></div>`;
const notice=(message,warning=false)=>`<div class="notice ${warning?'warning':''}">${message}</div>`;
const locationKinds=[['Client','Client · gives loads'],['Warehouse','Warehouse / depot · gives loads'],['Other','Other · may give loads'],['Unloading only','Unloading only'],['Parking','Parking / truck stop']];
// Default loading time for a truck's next order: the chosen time, or later if the truck is still busy then.
const truckFreeFrom=(truckId,wanted)=>{const latest=state.orders.filter(o=>o.truck_id===truckId&&o.status!=='Cancelled').map(o=>o.available_at).sort((a,b)=>Date.parse(b)-Date.parse(a))[0];return latest&&Date.parse(latest)>new Date(wanted).getTime()?localParts(latest):wanted;};
const contactResults=['Had a load','No load now','No answer','Call back later'];
const kindLabel=kind=>(locationKinds.find(([value])=>value===(kind||'Client'))||[,kind])[1].split(' · ')[0];
const telHref=phone=>'tel:'+String(phone).replace(/[^\d+]/g,'');
const contactLines=p=>{const parts=[p.contact_name?esc(p.contact_name):'',p.phone?`<a href="${esc(telHref(p.phone))}">☎ ${esc(p.phone)}</a>`:'',p.email?`<a href="mailto:${esc(p.email)}">✉ ${esc(p.email)}</a>`:''].filter(Boolean);return (parts.length?`<p class="contact-line">${parts.join(' · ')}</p>`:'')+(p.notes?`<p class="contact-notes">${esc(p.notes)}</p>`:'');};
const lastContactLine=c=>c?`<p class="last-contact ${c.result==='Had a load'?'good':''}">Last contact ${formatDate(c.at)} · <strong>${esc(c.result)}</strong>${c.note?' · '+esc(c.note):''}</p>`:'';
const empty=(title,message,action='',label='')=>`<div class="empty"><div class="empty-symbol">▦</div><h3>${title}</h3><div>${message}</div>${action?`<button class="btn primary" data-action="${action}">${label}</button>`:''}</div>`;

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',6500);}
async function api(path,data){const response=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':state.token}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok){const error=new Error(result.error||'Request failed');error.status=response.status;throw error;}return result;}
async function refresh(){state=await api('/api/state');if(!selectedDay)selectedDay=dayOf(state.now);$('#today-label').textContent=formatDay(dayOf(state.now),true);$('#nav-count').textContent=state.orders.filter(x=>x.status==='Planned'||x.status==='In transit').length;if(state.storage==='turso'){$('#storage-title').textContent='Cloud workspace';$('#storage-detail').textContent='Turso · Synced to the cloud';}render();if(view==='upcoming')await loadUpcoming();}
function navigate(next){view=next;render();$('#main').focus();if(next==='upcoming')loadUpcoming();}
function heading(title,subtitle,action='',label=''){return `<div class="heading"><div><div class="eyebrow">MALCOMTRANS / OPERATIONS</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action?`<div class="actions"><button class="btn primary" data-action="${action}">＋ ${label}</button></div>`:''}</div>`;}
function render(){for(const el of document.querySelectorAll('.nav'))el.classList.toggle('active',el.dataset.view===view);$('#breadcrumb').textContent=names[view];$('#main').innerHTML=view==='board'?boardView():view==='planner'?plannerView():view==='upcoming'?upcomingView():view==='settings'?settingsView():view==='analytics'?analyticsView():directoryView();}

async function loadUpcoming(){const request=++upcomingRequest,offset=weekOffset,count=weekCount;upcomingData=null;upcomingError='';if(view==='upcoming')render();try{const result=await api('/api/upcoming',{week_offset:offset,week_count:count});if(request===upcomingRequest){upcomingData=result;state.now=result.now;if(view==='upcoming')render();}}catch(error){if(request===upcomingRequest){upcomingError=error.message;if(view==='upcoming')render();}}}
function weekStart(day){const weekday=new Date(day+'T12:00:00Z').getUTCDay();return addDays(day,-((weekday+6)%7));}
// Dispatch-clock (Europe/Madrid) helpers.
function dispatchParts(ms){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(ms)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));}
function dispatchMidnight(day){const desired=Date.parse(day+'T00:00:00Z');let instant=desired;for(let i=0;i<3;i++){const p=dispatchParts(instant);const wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);instant+=desired-wall;}return instant;}
function dispatchStamp(ms){const p=dispatchParts(ms),wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute),offset=Math.round((wall-ms)/60000),pad=n=>String(n).padStart(2,'0');return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}${offset<0?'-':'+'}${pad(Math.floor(Math.abs(offset)/60))}:${pad(Math.abs(offset)%60)}`;}
function upcomingView(){const monday=weekStart(dayOf(state.now));const filtered=window=>(!upcomingTruck||window.truck_id===Number(upcomingTruck))&&(!upcomingOperation||window.operation===upcomingOperation);const weeks=upcomingData?.weeks||[];const windows=weeks.flatMap(w=>w.windows.filter(filtered));const truckIds=new Set(windows.map(w=>w.truck_id));
  return heading('Upcoming planning','Availability by tractor registration. Monday to Sunday, up to two weeks ahead.','new-order','New loading order')+`
  <section class="panel"><div class="upcoming-controls"><div class="field"><label for="upcoming-week">Starting week</label><select id="upcoming-week">${['This week','Next week','In 2 weeks'].map((label,index)=>`<option value="${index}" ${weekOffset===index?'selected':''}>${label} · ${formatDay(addDays(monday,index*7))} – ${formatDay(addDays(monday,index*7+6))}</option>`).join('')}</select></div><div class="field"><label for="upcoming-count">Show</label><select id="upcoming-count"><option value="1" ${weekCount===1?'selected':''}>1 calendar week</option><option value="2" ${weekCount===2?'selected':''} ${weekOffset===2?'disabled':''}>2 consecutive weeks</option></select></div>${searchSelectField('Truck','upcoming_truck',state.trucks.filter(t=>t.active&&!t.archived_at).map(t=>({id:t.id,label:t.plate,hint:t.operation})),upcomingTruck,{empty:'All active trucks',hiddenId:'upcoming-truck',placeholder:'All active trucks · type to search'})}<div class="field"><label for="upcoming-operation">Operation</label><select id="upcoming-operation"><option value="">All operations</option>${['International','National','Local'].map(value=>`<option ${upcomingOperation===value?'selected':''}>${value}</option>`).join('')}</select></div><button class="btn small" data-action="refresh-upcoming">↻ Refresh</button></div><div class="upcoming-horizon">Planning horizon: this week through ${formatDay(addDays(monday,20))}. Only future free windows of at least 2 hours are shown.</div></section>
  ${upcomingError?`<div class="form-error">${esc(upcomingError)}</div>`:!upcomingData?'<section class="panel loading">Checking weekly availability…</section>':`
  <div class="upcoming-summary"><div><strong>${weeks.length}</strong><span>${weeks.length===1?'week selected':'weeks selected'}</span></div><div><strong>${truckIds.size}</strong><span>trucks with free time</span></div><div><strong>${windows.length}</strong><span>free windows across selected weeks</span></div></div>
  ${weeks.map(week=>{const entries=week.windows.filter(filtered);const unavailable=week.scheduled.filter(t=>(!upcomingTruck||t.truck_id===Number(upcomingTruck))&&(!upcomingOperation||state.trucks.find(truck=>truck.id===t.truck_id)?.operation===upcomingOperation));return `<section class="panel upcoming-week" data-week-start="${week.start}"><div class="panel-head"><div><div class="eyebrow">WEEK ${week.week_number} · ${week.year}</div><h2>${formatDay(week.start)} – ${formatDay(week.end)}</h2><p>${entries.length} free ${entries.length===1?'window':'windows'} · ${new Set(entries.map(w=>w.truck_id)).size} trucks</p></div>${badge('Monday → Sunday','gray')}</div>${entries.length?`<div class="weekly-window-grid">${entries.map((window,index)=>weeklyWindow(window,week,index)).join('')}</div>`:empty('No free windows in this week','There is no known future availability of at least 2 hours for this selection.')}<div class="weekly-footnote">${unavailable.length?`<details><summary>${unavailable.length} trucks without a known free window this week</summary><p>${unavailable.map(t=>esc(t.plate)).join(' · ')}</p><p>They may be booked, become available later, or have gaps shorter than 2 hours.</p></details>`:entries.length?'All trucks with known availability have a free window in this week.':'No confirmed availability for this selection. Check missing details below.'}</div></section>`;}).join('')}
  ${upcomingData.unknown.length?`<section class="panel padded"><details><summary>${upcomingData.unknown.length} active trucks need availability details</summary>${upcomingData.unknown.map(t=>`<p class="subtitle"><strong>${esc(t.plate)}</strong> · ${esc(t.reason)}</p>`).join('')}</details></section>`:''}
  ${notice('Availability follows the orders for each tractor and reported location, not driver assignments or live GPS. Confirm driver hours, rest and positioning before assigning a load. A free window that crosses Sunday is split between the selected weeks.')}`}`;
}
function weeklyWindow(window,week,index){const end=window.week_end_boundary?`Sun ${week.end.slice(8)} · 23:59`:formatDate(window.until);return `<article class="weekly-window"><div class="weekly-window-head"><h3>${esc(window.plate)}</h3>${badge(window.operation,'gray')}</div><p class="weekly-driver">${esc(window.driver_name)} · ${esc(window.carrier)}</p><div class="weekly-location"><span>Available near</span><strong>${esc(window.location.city)}</strong><small>${esc(window.location.company)} · ${esc(window.location.postal_code)}, ${esc(window.location.country)}</small></div><div class="weekly-times"><div><span>FROM</span><strong>${formatDate(window.from)}</strong></div><div><span>${window.week_end_boundary?'THROUGH WEEK END':window.next_order?'UNTIL NEXT BOOKING':'AVAILABLE UNTIL'}</span><strong>${end}</strong></div></div><div class="weekly-source"><strong>${hours(window.hours)} free in this week</strong><p>${window.next_order?'Before '+esc(window.next_order):'No next booking inside this window.'}</p><p>Position: ${esc(window.source)}<br>Known since ${formatDate(window.known_since)}</p></div><div class="weekly-actions"><button class="btn small primary" data-action="nearby" data-id="${window.location.id}" data-context="${esc(`${window.plate} · free from ${formatDate(window.from)}`)}">🏢 Companies nearby</button><button class="btn small" data-action="upcoming-open-day" data-truck="${window.truck_id}" data-date="${dayOf(window.from)}">Open daily plan ↗</button></div></article>`;}
// "Companies nearby": who to call for the next load around a truck's free position.
let nearbyQuery=null;
async function openNearby(query){nearbyQuery=query;const origin=getLocation(query.location_id);showModal('Companies nearby',`<div class="nearby-head"><p class="subtitle">${esc(query.context||'')}${query.context?'<br>':''}Around <strong>${esc(placeLabel(origin))}</strong></p><div class="nearby-controls"><div class="field"><label for="nearby-radius">Radius</label><select id="nearby-radius">${[50,100,150,250,400].map(r=>`<option value="${r}" ${r===query.radius_km?'selected':''}>${r} km</option>`).join('')}</select></div><label class="checkbox"><input type="checkbox" id="nearby-all" ${query.include_all?'checked':''}><span>Also show parking and unloading-only sites</span></label></div></div><div id="nearby-results"><div class="loading">Looking for saved companies…</div></div>`,'UPCOMING PLANNING / NEXT LOAD');
  try{renderNearby(await api('/api/nearby',query));}catch(error){$('#nearby-results').innerHTML=notice(esc(error.message),true);}}
function renderNearby(result){const list=result.companies;$('#nearby-results').innerHTML=(result.note?notice(esc(result.note),true):'')+(list.length?`<p class="subtitle">${list.length} ${list.length===1?'company':'companies'} within ${result.radius_km} km · straight-line distance (by road usually 20–30% more).</p>`+list.map(nearbyCard).join(''):empty('No saved companies in this radius','Increase the radius, or add the companies you work with under Saved locations (with coordinates).','new-location','Add location'))+(result.missing_coordinates?`<p class="subtitle">${result.missing_coordinates} saved ${result.missing_coordinates===1?'company has':'companies have'} no coordinates and cannot be ranked by distance. Add them under Saved locations.</p>`:'');}
function nearbyCard(entry){const p=entry.location,history=entry.loads?`<strong>${entry.loads} ${entry.loads===1?'load':'loads'}</strong> from here · last ${formatDay(dayOf(entry.last_load_at))}${entry.destinations.length?' · went to '+esc(entry.destinations.join(', ')):''}`:'No loads from here yet';
  return `<article class="nearby-card ${entry.contacted_recently?'recent':''}"><div class="nearby-card-head"><div><h3>${esc(p.company)}</h3><p class="subtitle">${esc(p.city)} · ${esc(p.postal_code)}, ${esc(p.country)}</p></div><div class="nearby-km">${entry.same_site?'Same site':entry.km==null?'Same city':km(entry.km)}</div></div><div class="nearby-badges">${badge(kindLabel(p.kind),p.kind==='Client'?'':'gray')}${entry.contacted_recently?badge('Contacted in the last 3 days','amber'):''}</div>${contactLines(p)||'<p class="subtitle">No phone or email saved · <button class="link-button" data-action="edit-location" data-id="'+p.id+'">add contact</button></p>'}<p class="nearby-history">${history}</p>${lastContactLine(entry.last_contact)}<div class="actions"><button class="btn small" data-action="log-contact" data-id="${p.id}">☎ Log contact</button></div><div data-contact-slot="${p.id}"></div></article>`;}
function contactForm(locationId){return `<form class="contact-form" data-location="${locationId}">${errorBox}<div class="field"><label>Result</label><select name="result" required><option value="">Choose…</option>${contactResults.map(r=>`<option>${r}</option>`).join('')}</select></div><div class="field"><label>Note (optional)</label><input name="note" maxlength="500" placeholder="e.g. load Thursday to Lyon, 1.450 €"></div><div class="form-actions"><button type="button" class="btn small" data-action="cancel-contact">Cancel</button><button type="submit" class="btn small primary">Save contact</button></div></form>`;}

/* Journeys: every order is an ordered list of stops (older orders fall back to loading → unloading). */
const stopIcon={Loading:'↗',Unloading:'↙','Trailer swap':'⇄'};
function orderStops(o){if(o.stops?.length)return o.stops;const done=o.status==='Completed'?'Done':'Planned';return [{seq:1,kind:'Loading',location_id:o.loading_id,planned_at:o.pickup_at,status:done,done_at:null,leg_km:0},{seq:2,kind:'Unloading',location_id:o.unloading_id,planned_at:o.unloading_at,status:done,done_at:null,leg_km:o.distance_km}];}
const deliveryDay=o=>dayOf(o.delivered_at||o.unloading_at);
function nextStop(o){return ['Cancelled','Completed'].includes(o.status)?null:orderStops(o).find(s=>s.status!=='Done')||null;}
function lastDoneStop(o){return orderStops(o).filter(s=>s.status==='Done').pop()||null;}
function stopKindLabel(o,s){const n=orderStops(o).length;return s.kind==='Trailer swap'?'Trailer swap':s.kind==='Loading'?(s.seq===1?'Loading':'Extra loading'):(s.seq===n?'Unloading':'Extra unloading');}
function confirmLabel(o,s){return s.kind==='Loading'?'✓ Loaded':s.kind==='Trailer swap'?'✓ Swap done':s.seq===orderStops(o).length?'✓ Delivered':'✓ Unloaded';}
function trailerChain(o){return [o.trailer||'no trailer',...orderStops(o).filter(s=>s.kind==='Trailer swap').map(s=>s.pick_trailer)].join(' → ');}
function routeText(o){return orderStops(o).map(s=>stopIcon[s.kind]+' '+(getLocation(s.location_id)?.city||'?')).join(' → ');}
function orderStatusBadge(o){return badge(o.status,{Cancelled:'gray',Completed:'blue','In transit':'amber'}[o.status]||'');}
function stopIsLate(s){return s.status!=='Done'&&Date.parse(s.planned_at)<Date.now();}
function trailerWhere(t){if(t.archived_at)return 'Archived';if(t.parked_location_id){const p=getLocation(t.parked_location_id);return `Parked · ${p?.city||'?'}${t.parked_at?' since '+formatDate(t.parked_at):''}`;}const on=state.trucks.filter(x=>x.trailer_id===t.id&&!x.archived_at).map(x=>x.plate);return on.length?'On tractor '+on.join(', '):'Position not set';}
function filteredOrders(){const has=(o,kind,text)=>!text||orderStops(o).some(s=>s.kind===kind&&placeLabel(getLocation(s.location_id)).toLowerCase().includes(text.toLowerCase()));return state.orders.filter(order=>
  order.plate.toLowerCase().includes(filters.plate.toLowerCase())&&has(order,'Loading',filters.loading)&&has(order,'Unloading',filters.unloading)&&(!filters.operation||order.operation===filters.operation)&&(filters.status?order.status===filters.status:order.status!=='Cancelled'));}
function opportunities(){const endDay=addDays(selectedDay,period-1),list=[];const orders=state.orders.filter(o=>o.status!=='Cancelled');
  for(const order of orders){const truck=state.trucks.find(t=>t.id===order.truck_id);if(!truck?.active)continue;
    const ready=order.available_at;
    const next=orders.filter(o=>o.id!==order.id&&(o.truck_id===order.truck_id||o.driver_id===order.driver_id||(order.trailer&&o.trailer.toLowerCase()===order.trailer.toLowerCase()))&&new Date(o.pickup_at)>=new Date(ready)).sort((a,b)=>new Date(a.pickup_at)-new Date(b.pickup_at))[0];
    const from = new Date(ready)>new Date(state.now)?ready:state.now;
    if(next&&new Date(next.pickup_at)-new Date(from)<2*3600000)continue;
    if(dayOf(from)>endDay|| (next&&dayOf(next.pickup_at)<selectedDay))continue;
    if(filters.plate&&!order.plate.toLowerCase().includes(filters.plate.toLowerCase()))continue;
    if(filters.operation&&order.operation!==filters.operation)continue;
    if(filters.loading||filters.unloading){if(!placeLabel(getLocation(order.unloading_id)).toLowerCase().includes((filters.unloading||filters.loading).toLowerCase()))continue;}
    list.push({order,from,next});
  }
  return list.sort((a,b)=>new Date(a.from)-new Date(b.from));
}
/* Fleet board: one row per tractor for the selected day, every journey as a chain of stops. */
function orderTouchesDay(o,day){return orderStops(o).some(s=>dayOf(s.planned_at)===day||(s.done_at&&dayOf(s.done_at)===day))||(dayOf(o.pickup_at)<=day&&deliveryDay(o)>=day);}
function boardStop(o,s,day){const next=nextStop(o),isNext=next?.seq===s.seq,done=s.status==='Done',late=stopIsLate(s);return `<div class="board-stop ${s.kind==='Loading'?'k-load':s.kind==='Trailer swap'?'k-swap':'k-unload'} ${done?'done':''} ${isNext?'next':''} ${late&&!done?'late':''} ${dayOf(s.planned_at)===day?'':'other-day'}" title="${esc(stopKindLabel(o,s)+' · '+placeLabel(getLocation(s.location_id)))}"><span class="board-stop-place">${stopIcon[s.kind]} ${esc(getLocation(s.location_id)?.city||'?')}</span><small>${done?'✓ '+formatTime(s.done_at||s.planned_at):(dayOf(s.planned_at)===day?'':formatDay(dayOf(s.planned_at))+' ')+formatTime(s.planned_at)}${s.kind==='Trailer swap'?' · '+esc(s.pick_trailer):''}</small>${isNext?`<button class="board-confirm" data-action="confirm-stop" data-id="${o.id}" data-seq="${s.seq}" title="${esc(confirmLabel(o,s))}">${esc(confirmLabel(o,s))}</button>`:''}</div>`;}
function boardView(){const day=selectedDay,now=Date.now();const trucks=state.trucks.filter(t=>t.active&&!t.archived_at&&t.plate.toLowerCase().includes(filters.plate.toLowerCase())&&(!filters.operation||t.operation===filters.operation)).sort((a,b)=>a.plate.localeCompare(b.plate));
  const rows=trucks.map(t=>{const all=state.orders.filter(o=>o.truck_id===t.id&&o.status!=='Cancelled'),orders=all.filter(o=>orderTouchesDay(o,day)).sort((a,b)=>Date.parse(a.pickup_at)-Date.parse(b.pickup_at));const status=orders.some(o=>o.status==='In transit')?'In transit':orders.some(o=>o.status==='Planned')?'Planned':orders.length?'Done today':'Available';const lastJob=all.filter(o=>dayOf(o.available_at)<=day).sort((a,b)=>Date.parse(b.available_at)-Date.parse(a.available_at))[0];const base=lastJob?getLocation(lastJob.unloading_id):getLocation(t.location_id);const driver=state.drivers.find(d=>d.id===(orders[0]?.driver_id||t.driver_id));return {t,orders,status,lastJob,base,driver};});
  const todayStops=rows.flatMap(r=>r.orders.flatMap(o=>orderStops(o).filter(s=>dayOf(s.planned_at)===day).map(s=>({o,s}))));const pending=todayStops.filter(x=>x.s.status!=='Done'),late=pending.filter(x=>stopIsLate(x.s));
  const statusClass={'In transit':'amber',Planned:'',Available:'gray','Done today':'blue'};
  return heading('Fleet board','Every tractor and its journeys for '+formatDay(day,true)+(day===dayOf(state.now)?' · Today':'')+'. Confirm each stop where it happens.','new-order','New loading order')+`
  <section class="panel daily-date-panel"><div class="panel-head"><div><h2>Day</h2><p>Stops are shown on their planned day; journeys crossing midnight stay visible on every day they cover.</p></div><div class="actions"><button class="btn small" data-action="prev-day">‹ Previous day</button><input type="date" id="planning-date" value="${day}" aria-label="Board date"><button class="btn small" data-action="next-day">Next day ›</button><button class="btn primary small" data-action="today">Today</button></div></div>
  <div class="filters"><div class="filter"><label for="filter-plate">Tractor registration</label><input id="filter-plate" data-filter="plate" data-suggest="plates" autocomplete="off" placeholder="Type or pick a registration" value="${esc(filters.plate)}"></div><div class="filter"><label for="filter-operation">Operation</label><select id="filter-operation" data-filter="operation"><option value="">All operations</option>${['International','National','Local'].map(v=>`<option ${filters.operation===v?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn small" data-action="clear-filters">Reset</button></div></section>
  <div class="stats daily-stats board-stats"><div class="stat"><div class="stat-top">In transit<span class="stat-icon">⇢</span></div><strong>${rows.filter(r=>r.status==='In transit').length}</strong><small>Loaded, not yet delivered</small></div><div class="stat"><div class="stat-top">Stops to confirm<span class="stat-icon">✓</span></div><strong>${pending.length}</strong><small>${todayStops.length-pending.length} of ${todayStops.length} confirmed this day</small></div><div class="stat"><div class="stat-top">Overdue stops<span class="stat-icon">!</span></div><strong class="${late.length?'late-text':''}">${late.length}</strong><small>Planned time passed, not confirmed</small></div><div class="stat"><div class="stat-top">Available tractors<span class="stat-icon">○</span></div><strong>${rows.filter(r=>r.status==='Available').length}</strong><small>No journey on this day</small></div></div>
  <section class="panel"><div class="panel-head"><div><h2>Tractors <span class="section-count">${rows.length}</span></h2><p>Green = confirmed · outlined = next stop to confirm · red = overdue · faded = other day.</p></div></div>
  ${rows.length?`<div class="board">${rows.map(r=>`<div class="board-row ${r.status==='Available'?'idle':''}"><div class="board-truck"><strong>${esc(r.t.plate)}</strong><small>${esc(r.driver?.name||'Driver not assigned')}</small><small>Trailer ${esc(r.t.trailer||'—')}</small>${badge(r.t.operation,'gray')}</div><div class="board-journeys">${r.orders.length?r.orders.map(o=>`<div class="board-journey"><div class="board-journey-head"><button class="link-button" data-action="order-detail" data-id="${o.id}">${esc(o.number)}</button>${orderStatusBadge(o)}<small>${orderStops(o).length} stops · ${km(o.distance_km)}</small></div><div class="board-chain">${orderStops(o).map(s=>boardStop(o,s,day)).join('<span class="board-arrow">›</span>')}</div></div>`).join(''):`<div class="board-free">Free${r.base?` · near <strong>${esc(r.base.city)}</strong>`:''}${r.lastJob?` since ${formatDate(r.lastJob.available_at)}`:r.t.available_from?` from ${formatDate(r.t.available_from)}`:''} <button class="link-button" data-action="board-new-order" data-id="${r.t.id}">Plan a loading ↗</button></div>`}</div><div class="board-status">${badge(r.status,statusClass[r.status])}</div></div>`).join('')}</div>`:empty('No active tractors','Add tractors in the directory, or reset the filters.')}</section>`;}
function dayStops(orders,kind){const list=[];for(const order of orders)for(const stop of orderStops(order))if(stop.kind===kind&&dayOf(stop.planned_at)===selectedDay)list.push({order,stop});return list.sort((a,b)=>Date.parse(a.stop.planned_at)-Date.parse(b.stop.planned_at));}
function dailyStopSection(entries,kind){const loading=kind==='Loading',swap=kind==='Trailer swap',key=swap?'swap':loading?'loading':'unloading',dateIsToday=selectedDay===dayOf(state.now),title=swap?'Trailer swaps':kind,label=dateIsToday?title+' today':title+' · '+formatDay(selectedDay);if(swap&&!entries.length)return '';
  const help=swap?'Trucks leaving one trailer and picking up another. Confirming the swap marks the left trailer Parked at that place.':loading?'Every loading stop on this date (first and extra loadings), ordered by time. Confirm with ✓ Loaded.':'Every unloading stop on this date, ordered by estimated time. ✓ Delivered on the last stop completes the order.';
  return `<section class="panel daily-stop-section daily-${key}" data-daily-section="${key}"><div class="panel-head"><div><h2><span class="daily-stop-icon">${stopIcon[kind]}</span> ${label} <span class="section-count">${entries.length} ${entries.length===1?'stop':'stops'}</span></h2><p>${help}</p></div>${badge(swap?'Swap':kind,swap?'blue':loading?'':'amber')}</div>${entries.length?`<div class="schedule journey-schedule"><table><thead><tr><th>Truck & driver · this stop</th><th>Complete journey · all stops</th><th>Available after delivery</th><th>Order · confirm stop</th></tr></thead><tbody>${entries.map(entry=>journeyRow({...entry,day:selectedDay})).join('')}</tbody></table></div>`:empty(loading?'No loading on this day':'No unloading on this day','No stops match this date and the selected filters.')}</section>`;}
function plannerView(){const orders=filteredOrders(),loading=dayStops(orders,'Loading'),unloading=dayStops(orders,'Unloading'),swaps=dayStops(orders,'Trailer swap'),opp=opportunities();const dateLabel=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(selectedDay+'T12:00:00Z')).toUpperCase();
  return heading(dateLabel,'Daily planning · '+formatDay(selectedDay,true)+(selectedDay===dayOf(state.now)?' · Today':''),'new-order','New loading order')+`
  <section class="panel daily-date-panel"><div class="panel-head"><div><h2>Choose your planning day</h2><p>Loading and unloading for one date. All times use the Europe/Madrid dispatch clock.</p></div><div class="actions"><button class="btn small" data-action="prev-day">‹ Previous day</button><input type="date" id="planning-date" value="${selectedDay}" aria-label="Planning date"><button class="btn small" data-action="next-day">Next day ›</button><button class="btn primary small" data-action="today">Today</button></div></div>
  <div class="filters"><div class="filter"><label for="filter-plate">Tractor registration</label><input id="filter-plate" data-filter="plate" data-suggest="plates" autocomplete="off" placeholder="Type or pick a registration" value="${esc(filters.plate)}"></div><div class="filter wide"><label for="filter-loading">Loading place</label><input id="filter-loading" data-filter="loading" data-suggest="places" autocomplete="off" placeholder="City, company or postcode" value="${esc(filters.loading)}"></div><div class="filter wide"><label for="filter-unloading">Unloading place</label><input id="filter-unloading" data-filter="unloading" data-suggest="places" autocomplete="off" placeholder="City, company or postcode" value="${esc(filters.unloading)}"></div><div class="filter"><label for="filter-operation">Operation</label><select id="filter-operation" data-filter="operation"><option value="">All operations</option>${['International','National','Local'].map(v=>`<option ${filters.operation===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter"><label for="filter-status">Order status</label><select id="filter-status" data-filter="status"><option value="">All active</option>${['Planned','In transit','Completed','Cancelled'].map(v=>`<option ${filters.status===v?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn small" data-action="clear-filters">Reset</button></div>
  </section>
  <div class="stats daily-stats"><div class="stat"><div class="stat-top">Loading stops<span class="stat-icon">↗</span></div><strong>${loading.length}</strong><small>${loading.filter(e=>e.stop.status==='Done').length} confirmed</small></div><div class="stat"><div class="stat-top">Unloading stops<span class="stat-icon">↙</span></div><strong>${unloading.length}</strong><small>${unloading.filter(e=>e.stop.status==='Done').length} confirmed${swaps.length?` · ${swaps.length} trailer swap${swaps.length===1?'':'s'}`:''}</small></div><div class="stat"><div class="stat-top">Reload opportunities<span class="stat-icon">⌁</span></div><strong>${opp.length}</strong><small class="positive">Free windows for the selected day</small></div></div>
  ${dailyStopSection(loading,'Loading')}
  ${dailyStopSection(swaps,'Trailer swap')}
  ${dailyStopSection(unloading,'Unloading')}
  <section class="panel"><div class="panel-head"><div><h2>Daily reload windows <span class="section-count">${opp.length} windows</span></h2><p>Planned availability after unloading. A driving break or rest may still be needed before the next trip.</p></div><button class="btn small" data-view="upcoming">Open weekly planning →</button></div>${opp.length?`<div class="alert-grid">${opp.slice(0,12).map(({order,from,next})=>`<article class="opportunity"><h3>${esc(order.plate)} ${badge(order.operation,'gray')}</h3><p><strong>${esc(getLocation(order.unloading_id)?.city)}</strong> · ${esc(getLocation(order.unloading_id)?.company)}</p><p>${esc(order.driver_name)} · Ready ${formatDate(from)}<br>${next?'Until '+formatDate(next.pickup_at):'No next loading assigned'}</p><button class="link-button" data-action="reload-order" data-id="${order.id}">Plan next loading ↗</button></article>`).join('')}</div>`:empty('No open reload windows','Add a loading order to see when a truck becomes available after unloading.')}</section>`;
}
function journeyStop(o,s,active){const point=getLocation(s.location_id),kindClass=s.kind==='Loading'?'loading-stop':s.kind==='Trailer swap'?'swap-stop':'unloading-stop',done=s.status==='Done';return `<div class="journey-stop ${kindClass} ${active?'active-stop':'context-stop'} ${done?'done-stop':''} ${stopIsLate(s)&&o.status!=='Cancelled'?'late-stop':''}"><div class="stop-label">${stopIcon[s.kind]} ${stopKindLabel(o,s)}${active?'<span>THIS STOP</span>':''}</div><strong>${esc(point?.city||'Unknown location')}</strong><div class="stop-company">${esc(point?.company)}</div><div class="stop-address">${esc(point?.postal_code)} · ${esc(point?.country)}</div>${s.kind==='Trailer swap'?`<div class="stop-swap">Leave ${esc(s.drop_trailer||'—')} · take ${esc(s.pick_trailer)}</div>`:''}<div class="stop-time">${done?`✓ ${s.done_at?formatDate(s.done_at):'Done'}`:(active?formatTime(s.planned_at):formatDate(s.planned_at))}${!done&&s.seq>1?'<span>estimated</span>':''}</div></div>`;}
function journeyChain(o,activeSeq){return orderStops(o).map((s,i)=>(i?`<div class="journey-connector"><span>→</span><small>${km(s.leg_km)}</small></div>`:'')+journeyStop(o,s,s.seq===activeSeq)).join('');}
function stopAction(o,s){if(o.status==='Cancelled')return '';if(s.status==='Done')return `<span class="stop-confirmed">${confirmLabel(o,s)} ${s.done_at?formatTime(s.done_at):''}</span>`;const next=nextStop(o);return next?.seq===s.seq?`<button class="btn small primary confirm-stop" data-action="confirm-stop" data-id="${o.id}" data-seq="${s.seq}">${confirmLabel(o,s)}</button>`:`<small class="muted">After stop ${next?.seq} is confirmed</small>`;}
function completedTripsOnDay(truckId,day){return state.orders.filter(order=>order.truck_id===truckId&&order.status==='Completed'&&deliveryDay(order)===day).length;}
function tripProgressBadge(order,day){const count=completedTripsOnDay(order.truck_id,day),done=count>=4,label=`${order.plate}: ${count} completed trips out of a daily target of 4 on ${formatDay(day,true)}. Counts completed orders by unloading date, across all locations.`;return `<div class="journey-progress"><span class="daily-trip-progress ${done?'target-reached':'target-pending'}" title="${esc(label)}" aria-label="${esc(label)}">${done?'✓':'◷'} ${count} / 4 trips</span></div>`;}
function journeyRow({order:o,stop:s,day}){const stops=orderStops(o),activityClass=s.kind==='Loading'?'loading-activity':s.kind==='Trailer swap'?'swap-activity':'unloading-activity';return `<tr class="journey-row" data-order-id="${o.id}" data-stop-seq="${s.seq}" data-planning-day="${day}"><td class="vehicle-cell"><strong>${esc(o.plate)}</strong><small>Trailer ${esc(trailerChain(o))}</small><div class="journey-driver">${esc(o.driver_name)}</div><small>${esc(o.carrier)}</small><small>${badge(o.operation,'gray')}</small><div class="vehicle-activity"><div class="activity-label ${activityClass}">${stopIcon[s.kind]} ${stopKindLabel(o,s)} <b>${s.seq>1&&s.status!=='Done'?'≈ ':''}${formatTime(s.status==='Done'&&s.done_at?s.done_at:s.planned_at)}</b></div><small>Stop ${s.seq} of ${stops.length}</small></div></td><td class="journey-cell">${tripProgressBadge(o,day)}<div class="journey-stops">${journeyChain(o,s.seq)}</div></td><td class="ready-cell"><div class="ready-label">${o.status==='Cancelled'?'Cancelled order':o.status==='Completed'?'Delivered':'Planned availability'}</div><strong>${formatDate(o.status==='Completed'&&o.delivered_at?o.delivered_at:o.available_at)}</strong><small>At ${esc(getLocation(o.unloading_id)?.city)}</small>${['Planned','In transit'].includes(o.status)?'<small>Check remaining driver hours</small>':''}</td><td class="order-cell"><button class="link-button" data-action="order-detail" data-id="${o.id}">${esc(o.number)}</button><small>${orderStatusBadge(o)}</small>${stopAction(o,s)}<button class="journey-open" data-action="order-detail" data-id="${o.id}">View journey ↗</button></td></tr>`;}

const archiveReasons=['Sold','Scrapped / end of life','Lease or rental ended','Transferred to another company','Added by mistake','Other'];
let showArchived=false;
function plannedUsing(type,record){return state.orders.filter(o=>o.status==='Planned'&&(type==='trucks'?o.truck_id===record.id:o.trailer_id===record.id));}
function cardDelete(type,record){if(record.archived_at)return `<button class="btn small" data-action="restore-master" data-type="${type}" data-id="${record.id}">↺ Restore</button>`;const planned=plannedUsing(type,record);return planned.length?`<button class="btn small danger" disabled title="Planned orders: ${esc(planned.map(o=>o.number).join(', '))}. Complete, cancel or move them first.">Delete</button>`:`<button class="btn small danger" data-action="archive-master" data-type="${type}" data-id="${record.id}">Delete</button>`;}
function statusBadge(record){return record.archived_at?badge('Archived · '+record.archive_reason,'amber'):badge(record.active?'Active':'Inactive',record.active?'':'gray');}
function archivedLine(record){return record.archived_at?`<br><span class="archived-line">Deleted ${formatDate(record.archived_at)}${record.archive_note?' · '+esc(record.archive_note):''}. Trip history is kept.</span>`:'';}
function openArchive(type,id){const record=state[type].find(x=>x.id===Number(id));if(!record)return;const label=type==='trucks'?'tractor':'trailer';const assigned=type==='trailers'?state.trucks.filter(t=>t.trailer_id===record.id&&!t.archived_at).map(t=>t.plate):[];const trips=state.orders.filter(o=>type==='trucks'?o.truck_id===record.id:o.trailer_id===record.id).length;
  showModal(`Delete ${label} ${record.plate}`,`<form id="archive-form" data-type="${type}" data-id="${record.id}" data-plate="${esc(record.plate)}">${errorBox}${notice(`The ${label} disappears from the directory, planning and search lists. ${trips?`Its ${trips} trip${trips===1?'':'s'} stay in history and analytics.`:'No trips are linked to it.'} Nothing is erased: you can restore it from <strong>Show archived</strong>.${assigned.length?`<br>It will also be removed as default trailer from: <strong>${esc(assigned.join(', '))}</strong>.`:''}`)}<fieldset class="reason-list"><legend>Reason</legend>${archiveReasons.map((reason,index)=>`<label class="reason-option"><input type="radio" name="reason" value="${esc(reason)}" required><span>${esc(reason)}</span></label>`).join('')}</fieldset><div class="field"><label for="f-archive-note">Note <span class="muted">(required for “Other”, e.g. buyer or date)</span></label><textarea id="f-archive-note" name="note" maxlength="500" placeholder="Optional details…"></textarea></div><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn danger">Delete ${label}</button></div></form>`,'DIRECTORY / DELETE');}
function directoryView(){const type=view,all=state[type],archivable=type==='trucks'||type==='trailers',archivedCount=archivable?all.filter(x=>x.archived_at).length:0,items=archivable&&!showArchived?all.filter(x=>!x.archived_at):all;let body='';
  if(type==='drivers')body=items.map(d=>`<article class="directory-card"><h3>${esc(d.name)}</h3>${badge(d.active?'Active':'Inactive',d.active?'':'gray')}<p>${esc(d.carrier)}<br>${esc(d.phone||'No phone number')}<br>DNI / NIE: ${esc(d.dni_nie||'Not provided')}<br>${state.trucks.filter(t=>t.driver_id===d.id&&!t.archived_at).map(t=>esc(t.plate)).join(', ')||'No default truck'}</p><div class="actions"><button class="btn small" data-action="edit-driver" data-id="${d.id}">Edit driver</button></div></article>`).join('');
  if(type==='trucks')body=items.map(t=>`<article class="directory-card ${t.archived_at?'archived':''}"><div class="actions"><h3>${esc(t.plate)}</h3>${badge(t.operation)}</div><p>Trailer <strong>${esc(t.trailer||'Not assigned')}</strong><br>Driver: ${esc(state.drivers.find(d=>d.id===t.driver_id)?.name||'Not assigned')}<br>Last reported base: ${esc(getLocation(t.location_id)?.city||'Not set')}<br>${t.available_from?'Base available: '+formatDate(t.available_from):'Base availability not set'}<br>${t.height} m high · ${t.length} m long · ${t.weight/1000} t gross${archivedLine(t)}</p><div class="actions">${statusBadge(t)}${t.archived_at?'':`<button class="btn small" data-action="edit-truck" data-id="${t.id}">Edit & assign</button>`}${cardDelete('trucks',t)}</div></article>`).join('');
  if(type==='trailers')body=items.map(t=>`<article class="directory-card ${t.archived_at?'archived':''}"><h3>${esc(t.plate)}</h3>${statusBadge(t)}<p><span class="trailer-where ${t.parked_location_id?'parked':''}">${t.parked_location_id?'🅿 ':''}${esc(trailerWhere(t))}</span><br>${esc(t.notes||'No notes')}${archivedLine(t)}</p><div class="actions">${t.archived_at?'':`<button class="btn small" data-action="edit-trailer" data-id="${t.id}">Edit trailer</button>`}${cardDelete('trailers',t)}</div></article>`).join('');
  if(type==='locations')body=items.map(p=>`<article class="directory-card"><div class="actions"><h3>${esc(p.city)}</h3>${badge(p.country,'gray')}${badge(kindLabel(p.kind),p.kind==='Client'?'':'gray')}</div><p><strong>${esc(p.company)}</strong><br>${esc(p.postal_code)} · ${esc(p.address||'Address not provided')}<br>${p.lat!=null?`Coordinates: ${p.lat}, ${p.lon}`:'Coordinates not set — manual routing available'}</p>${contactLines(p)}${lastContactLine(p.contacts?.[0])}<div class="actions"><button class="btn small" data-action="edit-location" data-id="${p.id}">Edit location</button><button class="btn small" data-action="log-contact" data-id="${p.id}">☎ Log contact</button></div></article>`).join('');
  const singular={drivers:'driver',trucks:'truck',trailers:'trailer',locations:'location'}[type];
  const sub={drivers:'Your drivers and partner carriers. Assign a default driver to each tractor.',trailers:'Registered trailers with separate plates. Select a saved trailer when assigning a tractor or trip.',trucks:'Tractor registrations, trailer assignments and truck profiles for routing.',locations:'Plain-text city and company names, with postcodes and optional verified coordinates.'}[type];
  return heading(names[type],sub,'new-'+singular,'Add '+singular)+`<div class="search-row"><input id="directory-search" type="search" placeholder="Search ${type}…" aria-label="Search ${type}"><span class="badge gray">${items.filter(x=>!x.archived_at).length} saved</span>${archivable?`<label class="checkbox show-archived"><input type="checkbox" id="show-archived" ${showArchived?'checked':''} ${archivedCount?'':'disabled'}><span>Show archived (${archivedCount})</span></label>`:''}</div><div class="directory-cards">${body||`<div class="panel span-2">${empty('Your '+type+' will appear here','Add your first '+singular+' to start building the planning.','new-'+singular,'Add '+singular)}</div>`}</div>`;
}
function settingsView(){return heading('Settings & backup','Routing connections, planning assumptions and a safe copy of your dispatch data.')+`<div class="settings-grid"><section class="panel padded"><h3>Truck routing · HERE</h3>${badge(state.here_configured?'API key configured':'Not configured',state.here_configured?'':'amber')}<p>Manual kilometres and driving hours work without an account. Automatic routes use HERE truck mode and the vehicle height, width, length and gross weight saved under Trucks.</p><p>To connect HERE, close the server and run in PowerShell:</p><code class="code">$env:HERE_API_KEY = 'your-key-here'\npython app.py</code><p>The key stays on the server, loaded from the environment or local configuration. Give the account access to Geocoding & Search and Routing. API requests send the selected coordinates, addresses and vehicle profile to HERE and may incur provider charges.</p><p><a href="https://docs.here.com/routing/docs/routing-v8-truck-routing" target="_blank" rel="noreferrer">HERE truck routing documentation ↗</a></p><h3>Location accuracy</h3><p>Confirm the geocoded result before saving. A city/postcode coordinate can represent the area, not the exact truck entrance. Add a street address or verified entrance coordinates for better routing.</p></section>
<section class="panel padded"><h3>Database backup</h3><p>Your fleet, locations and loading orders are stored in <strong>data/malcomtrans.sqlite3</strong>. This button creates a consistent SQLite backup while the app is running.</p><a class="btn primary" href="/api/backup" download>↓ Download database backup</a><p>To restore: stop the server, keep a copy of the current database, replace data/malcomtrans.sqlite3 with the backup, then restart.</p><h3>Local access</h3><p>This app listens on 127.0.0.1. Anyone with access to this computer can use its local data. It has no multi-user sign-in or live tracking.</p><h3>Project folder</h3><p>The project is inside an existing Python virtual environment. Back it up before recreating or deleting that environment.</p></section>
<section class="panel padded span-2"><h3>Single-driver EU planning model</h3><ul><li>9 hours driving per daily period; 45-minute break after 4.5 hours, or daily rest when due.</li><li>11-hour daily rest; a conservative 13-hour duty window includes loading and unloading.</li><li>56 hours in an ISO calendar week and 90 hours across two adjacent weeks; regular weekly rest of at least 45 hours, due no later than the supplied weekly-rest deadline.</li><li>Enter actual driving, duty and weekly hours at the loading appointment. “Carry forward” reuses previous planned orders. Unassigned gaps are assumed to be rest or breaks; confirm this against the tachograph.</li><li>10-hour extensions, reduced/split rests, multi-manning, compensation, working-time averaging, country/holiday driving bans, ferries and exceptional derogations are not modelled.</li><li>All displayed and entered times use one dispatch clock: Europe/Madrid, including daylight saving. Convert foreign local appointment times to this clock.</li><li>Route times, availability windows and nearby-company distances are planning estimates. They cannot certify compliance or replace driver confirmation and tachograph records.</li></ul><a href="https://transport.ec.europa.eu/transport-modes/road/social-provisions/driving-time-and-rest-periods_en" target="_blank" rel="noreferrer">European Commission: driving time and rest periods ↗</a></section></div>`;}

function showModal(title,content,kicker='DISPATCH WORKSPACE'){const modal=$('#modal');$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function showError(form,error){const el=$('.form-error',form);if(el){el.textContent=error.message;el.scrollIntoView({block:'nearest'});}else toast(error.message,true);}
function formObject(form){const obj=Object.fromEntries(new FormData(form));for(const input of form.querySelectorAll('input[type=checkbox]'))obj[input.name]=input.checked;return obj;}
function openMaster(type,id=null,returnTo=null){const item=state[type].find(x=>x.id===Number(id))||returnTo?.prefill||{};const singular={drivers:'driver',trucks:'truck',trailers:'trailer',locations:'location'}[type];let fields='';
  if(type==='drivers')fields=field('Driver name','name',item.name||'','text','required maxlength="200"')+field('DNI / NIE (optional)','dni_nie',item.dni_nie||'','text','maxlength="30" autocomplete="off"')+field('Phone','phone',item.phone||'','tel','maxlength="60"')+field('Carrier / company','carrier',item.carrier||'MalcomTrans','text','maxlength="200"');
  if(type==='trucks')fields=field('Tractor registration','plate',item.plate||'','text','required maxlength="30"')+trailerPicker('Assigned trailer',item.trailer_id,item.trailer)+selectField('Default driver','driver_id',options(state.drivers.filter(d=>d.active||d.id===item.driver_id),item.driver_id,d=>d.name+' · '+d.carrier,'Assign later'))+selectField('Operation','operation',['International','National','Local'].map(v=>`<option ${v===(item.operation||'International')?'selected':''}>${v}</option>`).join(''))+selectField('Known base / current reported location','location_id',options(state.locations,item.location_id,placeLabel,'Not set'))+field('Available at this location','available_from',localParts(item.available_from),'datetime-local','', 'Used only when there is no preceding planned unloading.')+`<div class="span-2 section-title">Full combination profile · tractor + trailer</div>`+field('Height (metres)','height',item.height??4,'number','step="0.01" min="0.5" max="6" required')+field('Width (metres)','width',item.width??2.55,'number','step="0.01" min="0.5" max="4" required')+field('Length (metres)','length',item.length??16.5,'number','step="0.01" min="2" max="30" required')+field('Gross / conservative laden weight (kg)','weight',item.weight??40000,'number','step="1" min="1000" max="100000" required');
  if(type==='trailers')fields=field('Trailer registration','plate',item.plate||'','text','required maxlength="30"')+field('Notes (optional)','notes',item.notes||'','text','maxlength="2000"')+`<div class="span-2 section-title">Position</div>`+selectField('Parked at','parked_location_id',options(state.locations,item.parked_location_id,placeLabel,'Not parked · on a tractor or unknown'))+field('Parked since','parked_at',localParts(item.parked_at),'datetime-local','','Set automatically when a trailer swap is confirmed. Empty = now.');
  if(type==='locations')fields=field('Company / loading or unloading site','company',item.company||'','text','required maxlength="200"')+field('City','city',item.city||'','text','required maxlength="200"')+field('Postal code','postal_code',item.postal_code||'','text','required maxlength="200"')+field('Country','country',item.country||'','text','required maxlength="200" placeholder="e.g. Spain"')+`<div class="span-2">${field('Street address / site entrance (optional)','address',item.address||'','text','maxlength="200"')}<button class="btn small" type="button" data-action="geocode" ${state.here_configured?'':'disabled'}>⌖ Find address with HERE</button>${!state.here_configured?'<p class="subtitle">You can save plain text now. Coordinates can be added manually or later with HERE.</p>':''}</div><div class="geocode-results" id="geocode-results"></div>`+field('Latitude (optional)','lat',item.lat??'','number','step="any" min="-90" max="90"')+field('Longitude (optional)','lon',item.lon??'','number','step="any" min="-180" max="180"')+`<input name="geo_label" type="hidden" value="${esc(item.geo_label||'')}"><div class="span-2">${notice('Plain-text city and company names are preserved as entered. Confirm coordinates before routing. Referenced locations retain their original address to preserve loading-order history.')}</div>`
    +`<div class="span-2 section-title">Company profile & contact · used by “Companies nearby”</div>`+selectField('Type','kind',locationKinds.map(([value,label])=>`<option value="${value}" ${value===(item.kind||'Client')?'selected':''}>${label}</option>`).join(''))+field('Contact person (optional)','contact_name',item.contact_name||'','text','maxlength="200"')+field('Phone / WhatsApp (optional)','phone',item.phone||'','tel','maxlength="60"')+field('Email (optional)','email',item.email||'','email','maxlength="200"')+`<div class="field span-2"><label for="f-notes">Notes (optional)</label><textarea id="f-notes" name="notes" maxlength="2000" placeholder="e.g. Loads often to France on Tuesdays and Thursdays · needs a curtainsider · pays at 60 days">${esc(item.notes||'')}</textarea></div>`;
  const deletable=item.id&&(type==='trucks'||type==='trailers'),planned=deletable?plannedUsing(type,item):[];
  const deleteControl=deletable?(planned.length?`<button type="button" class="btn danger" disabled title="Has planned orders">Delete ${singular}</button><p class="subtitle delete-hint">Planned orders ${esc(planned.map(o=>o.number).join(', '))} use it. Complete, cancel or move them before deleting.</p>`:`<button type="button" class="btn danger" data-action="archive-master" data-type="${type}" data-id="${item.id}">Delete ${singular}</button>`):'';
  const content=`<form id="master-form" data-type="${type}">${errorBox}<input name="id" type="hidden" value="${item.id||''}"><div class="form-grid">${fields}</div>${type!=='locations'?`<label class="checkbox"><input type="checkbox" name="active" ${item.active!==0?'checked':''}>Active ${singular}</label>`:''}<div class="form-actions">${deleteControl}<button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save ${singular}</button></div></form>`;
  showModal((id?'Edit ':'Add ')+singular,content);$('#master-form')._returnTo=returnTo;
}

const clockDefaults={drive_today:0,drive_since_break:0,duty_today:0,drive_week:0,drive_previous_week:0,weekly_rest_due_in:144};
const locationSignature=point=>['address','postal_code','city','country','company'].map(key=>point[key]||'').join('|');
const hasCoordinates=point=>point&&point.lat!=null&&point.lon!=null&&point.lat!==''&&point.lon!==''&&Number.isFinite(Number(point.lat))&&Number.isFinite(Number(point.lon));
function orderGeoBox(form,slot){const box=form.querySelector('[data-order-geo="'+slot+'"]');if(!box)return;const point=getLocation(form.elements[slot].value),job=form._geoJobs?.[slot];if(form.elements.route_mode.value!=='here'||!point){box.innerHTML='';return;}if(hasCoordinates(point)){box.innerHTML=`<div class="geo-confirmed">✓ Coordinates saved <span>${esc(point.geo_label||[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', '))}</span></div>`;return;}const label=slot==='loading_id'?'Loading':'Unloading',query=job?.id===point.id?job.query:[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', ');box.innerHTML=`<div class="order-geo-box"><strong>⌖ Confirm ${label.toLowerCase()} address</strong><p>${job?.status==='loading'?'Finding coordinates with HERE…':'Select the correct address below. Coordinates will be saved with this location.'}</p>${!point.address?'<p class="geo-area-warning">No street address is saved. A postal code may identify an area; refine the search to the site entrance.</p>':''}<label class="geo-search-label" for="order-query-${slot}">Address search</label><div class="inline-actions"><input id="order-query-${slot}" value="${esc(query)}" maxlength="600" aria-label="${label} address search"><button type="button" class="btn small" data-action="search-order-location" data-slot="${slot}" ${job?.status==='loading'?'disabled':''}>Search</button></div>${job?.error?`<div class="geo-inline-error">${esc(job.error)}</div>`:''}${job?.matches?.map((match,index)=>`<button type="button" class="geo-option" data-action="confirm-order-location" data-slot="${slot}" data-index="${index}"><strong>Confirm this address →</strong><span>${esc(match.label)}</span><small>${esc(match.result_type)} · ${match.lat}, ${match.lon}${['locality','administrativeArea','postalCode'].includes(match.result_type)?' · Area-level match — verify site entrance':''}</small></button>`).join('')||''}${job?.status==='ready'&&!job.matches.length?'<p>No matches. Add a street address and country, then search again.</p>':''}</div>`;}
async function searchOrderLocation(form,slot,queryOverride=null){const point=getLocation(form.elements[slot].value);if(!point||hasCoordinates(point))return;form._geoJobs??={};const signature=locationSignature(point),existing=form._geoJobs[slot];if(queryOverride===null&&existing?.id===point.id&&existing.signature===signature){orderGeoBox(form,slot);return existing.promise;}const query=queryOverride??[point.address,point.postal_code,point.city,point.country].filter(Boolean).join(', '),job={id:point.id,signature,query,status:'loading',matches:[],error:''};form._geoJobs[slot]=job;orderGeoBox(form,slot);job.promise=(async()=>{try{const response=await api('/api/geocode',{query});job.matches=response.matches;job.status='ready';}catch(error){job.error=error.message;job.status='error';}if(form.isConnected&&form._geoJobs[slot]===job)orderGeoBox(form,slot);})();return job.promise;}
async function ensureOrderCoordinates(form,search=false){if(form.elements.route_mode.value!=='here')return true;const slots=['loading_id','unloading_id'];for(const slot of slots)orderGeoBox(form,slot);if(search)await Promise.all(slots.map(slot=>searchOrderLocation(form,slot)));return slots.every(slot=>hasCoordinates(getLocation(form.elements[slot].value)));}
async function confirmOrderLocation(form,slot,index){const job=form._geoJobs?.[slot],point=getLocation(form.elements[slot].value),match=job?.matches[index];if(!point||!match||job.id!==point.id||job.signature!==locationSignature(point))throw new Error('The selected location changed. Search again before confirming.');const latestState=await api('/api/state'),latest=latestState.locations.find(p=>p.id===point.id);if(!latest||locationSignature(latest)!==job.signature)throw new Error('This address was edited elsewhere. Refresh the location list before confirming coordinates.');await api('/api/locations',{...latest,lat:match.lat,lon:match.lon,geo_label:match.label});state.locations=state.locations.map(p=>p.id===point.id?{...latest,lat:match.lat,lon:match.lon,geo_label:match.label}:p);await ensureOrderCoordinates(form,false);toast('Address confirmed. Coordinates saved for future orders.');}
let viaCounter=0;
const viaTitles={Loading:'↗ Extra loading',Unloading:'↙ Extra unloading','Trailer swap':'⇄ Trailer swap · drop current trailer, pick up another'};
function viaRow(stop={}){const uid=++viaCounter,kind=stop.kind||'Loading',swap=kind==='Trailer swap';
  const trailers=(state.trailers||[]).filter(t=>(t.active&&!t.archived_at)||t.id===Number(stop.pick_trailer_id)).map(t=>({id:t.id,label:t.plate,value:t.plate,hint:trailerWhere(t)}));
  return `<div class="via-stop" data-via data-kind="${esc(kind)}"><div class="via-head"><span class="stop-chip ${swap?'swap':kind==='Loading'?'loading':'unloading'}">${viaTitles[kind]}</span><button type="button" class="link-button" data-action="remove-via">Remove stop</button></div><div class="form-grid">
  <div class="field"><label>${swap?'Swap point':'Location'} · city & company</label><select data-via-field="location_id" required>${options(state.locations,stop.location_id,placeLabel)}</select></div>
  <div class="field"><label>${swap?'Swap duration (h)':kind==='Loading'?'Loading duration (h)':'Unloading duration (h)'}</label><input data-via-field="handling_hours" type="number" min="0" max="6" step="0.25" required value="${esc(stop.handling_hours??(swap?0.5:1))}"></div>
  ${swap?`<div class="span-2">${searchSelectField('Trailer picked up here','via_pick_'+uid,trailers,stop.pick_trailer_id,{empty:'Choose a trailer',newLabel:'trailer',newField:'via_new_'+uid,placeholder:'Search or type a new registration…',required:true})}<small class="subtitle">The current trailer is left here and marked <strong>Parked</strong> at this location when you confirm the swap.</small></div>`:''}
  <div class="field" data-manual-only><label>Planned arrival · from driver</label><input data-via-field="arrive_at" type="datetime-local" data-arrival value="${esc(localParts(stop.arrive_at||stop.planned_at))}"></div>
  <div class="field leg-field"><label>Distance from previous stop (km)</label><input data-via-field="leg_km" type="number" min="0" max="15000" step="0.1" value="${esc(stop.leg_km??'')}"></div>
  <div class="field leg-field" data-rules-only><label>Driving time from previous stop (h)</label><input data-via-field="leg_hours" type="number" min="0" max="240" step="0.01" value="${esc(stop.leg_hours??'')}"></div>
  </div></div>`;}
function viaData(form){return [...form.querySelectorAll('[data-via]')].map(row=>{const value=name=>row.querySelector(`[data-via-field="${name}"]`)?.value??'';const picker=row.querySelector('[data-search-select]');return {kind:row.dataset.kind,location_id:value('location_id'),arrive_at:value('arrive_at'),handling_hours:Number(value('handling_hours')||0),leg_km:Number(value('leg_km')||0),leg_hours:Number(value('leg_hours')||0),pick_trailer_id:picker?picker.querySelector('[data-search-hidden]').value:'',new_pick_trailer:picker?picker.querySelector('[data-search-newvalue]')?.value||'':''};});}
function orderData(form){const data=formObject(form);data.clock={};for(const key of Object.keys(clockDefaults)){data.clock[key]=Number(data['clock_'+key]);delete data['clock_'+key];}for(const key of Object.keys(data))if(/^via_(pick|new)_/.test(key))delete data[key];data.via=viaData(form);if(data.id)data.id=Number(data.id);else delete data.id;return data;}
function dispatchInputInstant(value){if(/[zZ]$|[+-]\d{2}:\d{2}$/.test(value))return Date.parse(value);const wanted=Date.parse(value.slice(0,16)+':00Z');let guess=wanted;for(let i=0;i<3;i++){const p=dispatchParts(guess);guess+=wanted-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);}return guess;}
function loadingRestSuggestion(data,creditFrom=null){const clock=data.clock||{},loading=Number(data.loading_hours??1),duty=Number(clock.duty_today||0),due=Number(clock.weekly_rest_due_in??144);if(!data.pickup_at||!Number.isFinite(loading)||loading<=0||(!Number.isFinite(duty))||(!Number.isFinite(due)))return null;const at=dispatchInputInstant(data.pickup_at),deadline=at+due*3600000;if(duty+loading<=13+0.00001&&at+loading*3600000<=deadline)return null;const restStart=creditFrom?Math.min(at,Date.parse(creditFrom)):at;let weekly=at+loading*3600000>deadline;let end=Math.max(at,restStart+11*3600000);if(end+loading*3600000>deadline)weekly=true;if(weekly)end=Math.max(at,restStart+45*3600000);const oldWeek=weekStart(dispatchStamp(at).slice(0,10)),newWeek=weekStart(dispatchStamp(end).slice(0,10)),weeks=Math.round((Date.parse(newWeek+'T00:00Z')-Date.parse(oldWeek+'T00:00Z'))/604800000);const nextClock={...clock,drive_today:0,drive_since_break:0,duty_today:0,drive_week:weeks>0?0:Number(clock.drive_week||0),drive_previous_week:weeks>1?0:weeks===1?Number(clock.drive_week||0):Number(clock.drive_previous_week||0),weekly_rest_due_in:weekly?144:Math.max(0,(deadline-end)/3600000)};return {pickup_at:dispatchStamp(end),clock:nextClock,rest_hours:weekly?45:11,remaining_hours:Math.max(0,(end-at)/3600000),credited:!!creditFrom,original_at:dispatchStamp(at)};}
const manualTiming=form=>form?.elements.timing?.value==='manual';
function renderLoadingRestSuggestion(form){if(manualTiming(form)){form._restSuggestion=null;$('#rest-suggestion',form).innerHTML='';return false;}const data=orderData(form),suggestion=loadingRestSuggestion(data,form._restCreditFrom);form._restSuggestion=suggestion;const box=$('#rest-suggestion',form);if(!suggestion){box.innerHTML='';return false;}box.innerHTML=notice(`<strong>The truck is free, but driver rest is needed before loading.</strong><br>Proposed loading: <strong>${formatDate(suggestion.pickup_at)}</strong> after ${suggestion.rest_hours} hours of ${suggestion.rest_hours===45?'weekly':'daily'} rest.${suggestion.credited?' The unassigned gap after the previous job counts toward this rest only if the driver actually rests.':' This proposal assumes uninterrupted rest from the selected time.'}<br><button type="button" class="btn small" data-action="apply-rest-suggestion">Use suggested loading time →</button>`,true);return true;}
async function carryOrderClock(form){if(manualTiming(form))return;const data=orderData(form),response=await api('/api/clock',data);if(!form.isConnected||form.elements.pickup_at.value!==data.pickup_at||String(form.elements.driver_id.value)!==String(data.driver_id))return;fillClock(response);const at=dispatchInputInstant(data.pickup_at),prior=state.orders.filter(o=>o.driver_id===Number(data.driver_id)&&o.status!=='Cancelled'&&o.id!==data.id&&Date.parse(o.available_at)<=at).sort((a,b)=>Date.parse(b.available_at)-Date.parse(a.available_at))[0];form._restCreditFrom=prior?.available_at||null;form._plannedClock=true;renderLoadingRestSuggestion(form);}
function openOrder(draft={}){const selected=state.trucks.find(t=>t.id===Number(draft.truck_id)),timing=draft.timing||'manual';const clock={...clockDefaults,...draft.clock};const clockFields=[['Driven today (h)','drive_today',9],['Driven since last break (h)','drive_since_break',4.5],['Duty elapsed today (h)','duty_today',13],['Driven this week (h)','drive_week',56],['Driven previous week (h)','drive_previous_week',56],['Weekly rest due in (h)','weekly_rest_due_in',144]].map(([label,key,max])=>field(label,'clock_'+key,Number(clock[key]).toFixed(2),'number',`required min="0" max="${max}" step="0.01"`)).join('');
  showModal(draft.id?'Edit loading order':'New loading order',`<form id="order-form">${errorBox}<div id="rest-suggestion" role="status"></div><input name="id" type="hidden" value="${draft.id||''}">
  ${!state.trucks.length||!state.drivers.length||state.locations.length<1?notice('Add a driver, truck and locations in the directory before saving an order.',true):''}
  <div class="form-grid">${searchSelectField('Tractor registration','truck_id',state.trucks.filter(t=>t.active&&!t.archived_at).map(t=>({id:t.id,label:t.plate,hint:t.operation})),draft.truck_id,{required:true,empty:'Choose a tractor',newLabel:'tractor',placeholder:'Search or type a new registration…'})}${selectField('Driver','driver_id',options(state.drivers.filter(d=>d.active),draft.driver_id||selected?.driver_id,d=>d.name+' · '+d.carrier)).replace('<select ','<select required ')}${trailerPicker('Trailer for this order',draft.trailer_id!==undefined?draft.trailer_id:(draft.trailer!==undefined?undefined:selected?.trailer_id),draft.trailer??selected?.trailer??'')}${field('Loading appointment · dispatch time','pickup_at',localParts(draft.pickup_at)||selectedDay+'T08:00','datetime-local','required')}
  <div class="span-2 section-title">Journey · stops in order</div>${selectField('Route calculation','route_mode',`<option value="manual" ${draft.route_mode!=='here'?'selected':''}>Manual kilometres & driving time per leg</option><option value="here" ${draft.route_mode==='here'?'selected':''} ${state.here_configured?'':'disabled'}>HERE truck route ${state.here_configured?'':'(API key required)'}</option>`)}<div class="field"><label for="f-timing">Arrival times</label><select id="f-timing" name="timing"><option value="manual" ${timing==='manual'?'selected':''}>I enter them · as told by the driver</option><option value="rules" ${timing==='rules'?'selected':''}>Calculate with EU driving rules (driver clock)</option></select><small data-manual-only>Enter the planned arrival at each stop. You can change it later when the driver calls.</small><small data-rules-only>Calculated from driving time, breaks and rests. Requires the driver's hours.</small></div>
  <div class="span-2 journey-editor">
  <div class="via-stop fixed-stop"><div class="via-head"><span class="stop-chip loading">① ↗ Loading</span></div><div class="form-grid"><div class="field"><label for="f-loading_id">Loading point · city & company</label><div class="inline-actions"><select name="loading_id" id="f-loading_id" required>${options(state.locations,draft.loading_id,placeLabel)}</select><button type="button" class="btn small" data-action="quick-location" data-slot="loading_id">＋ New</button></div><div data-order-geo="loading_id"></div></div>${field('Loading duration (h)','loading_hours',draft.loading_hours??1,'number','required min="0" max="6" step="0.25"')}</div></div>
  <div id="via-stops">${(draft.via||[]).map(stop=>viaRow(stop)).join('')}</div>
  <div class="via-add"><span>Add a stop before unloading:</span><button type="button" class="btn small" data-action="add-via" data-kind="Loading">＋ Extra loading</button><button type="button" class="btn small" data-action="add-via" data-kind="Unloading">＋ Extra unloading</button><button type="button" class="btn small" data-action="add-via" data-kind="Trailer swap">＋ Trailer swap</button></div>
  <div class="via-stop fixed-stop"><div class="via-head"><span class="stop-chip unloading">↙ Final unloading · delivery</span></div><div class="form-grid"><div class="field"><label for="f-unloading_id">Unloading point · city & company</label><div class="inline-actions"><select name="unloading_id" id="f-unloading_id" required>${options(state.locations,draft.unloading_id,placeLabel)}</select><button type="button" class="btn small" data-action="quick-location" data-slot="unloading_id">＋ New</button></div><div data-order-geo="unloading_id"></div></div>${field('Unloading duration (h)','unloading_hours',draft.unloading_hours??1,'number','required min="0" max="6" step="0.25"')}
  <div class="field" data-manual-only><label for="f-unloading_arrive_at">Planned arrival at unloading · from driver</label><input id="f-unloading_arrive_at" name="unloading_arrive_at" type="datetime-local" data-arrival value="${esc(localParts(draft.unloading_arrive_at))}"></div>
  ${field('Distance from previous stop (km)','distance_km',draft.distance_km??'','number','min="0" max="15000" step="0.1"','Road distance, used for the km totals in Analytics. Optional with manual times.')}<div class="field" data-rules-only><label for="f-driving_hours">Driving time from previous stop (h)</label><input id="f-driving_hours" name="driving_hours" type="number" min="0" max="240" step="0.01" value="${esc(draft.driving_hours??'')}"><small>Pure driving time. Breaks, rests and handling are added automatically.</small></div></div></div>
  </div>
  </div><details data-rules-only><summary>Driver clock at loading · hours already used</summary><p class="subtitle">Default zeros mean the driver starts fresh after qualifying rest. Enter actual hours or carry forward the previous planned order. Loading and unloading count as duty.</p><div class="form-grid">${clockFields}</div><button class="btn small" type="button" data-action="carry-clock">↻ Carry forward previous planning</button><p id="clock-message" class="subtitle"></p></details>
  <div class="field"><label for="f-notes">Dispatch notes / plain text</label><textarea id="f-notes" name="notes" maxlength="5000" placeholder="References, contact names, loading instructions…">${esc(draft.notes||'')}</textarea></div>
  <label class="checkbox" data-rules-only><input type="checkbox" name="clock_confirmed" required ${draft.clock_confirmed?'checked':''}><span>I verified the driver's clock and the truck's ability to reach this loading point. Unassigned gaps counted as rest are planning assumptions. The ETA is an estimate, not a compliance certificate.</span></label>
  <div id="order-preview"></div><div class="form-actions"><button type="button" class="btn" data-action="preview-order"><span data-manual-only>Check times</span><span data-rules-only>Calculate ETA</span></button><button type="submit" class="btn primary">${draft.id?'Save changes':'Create loading order'}</button></div></form>`,'LOADING ORDER / SINGLE DRIVER');
  syncRouteMode();syncTiming();renderLoadingRestSuggestion($('#order-form'));ensureOrderCoordinates($('#order-form'),true).catch(error=>showError($('#order-form'),error));
}
// Manual times: the dispatcher types each arrival; the driver clock and rest checks are not used.
function syncTiming(){const form=$('#order-form');if(!form)return;const manual=manualTiming(form);for(const el of form.querySelectorAll('[data-manual-only]'))el.hidden=!manual;for(const el of form.querySelectorAll('[data-rules-only]'))el.hidden=manual;for(const input of form.querySelectorAll('[data-arrival]'))input.required=manual;form.elements.clock_confirmed.required=!manual;syncRouteMode();renderLoadingRestSuggestion(form);}
function syncRouteMode(){const form=$('#order-form');if(!form)return;const manual=form.elements.route_mode.value==='manual',rules=!manualTiming(form);form.elements.distance_km.disabled=!manual;form.elements.distance_km.required=manual&&rules;form.elements.driving_hours.disabled=!manual||!rules;form.elements.driving_hours.required=manual&&rules;for(const input of form.querySelectorAll('[data-via-field=leg_km],[data-via-field=leg_hours]'))input.disabled=!manual;}
function previewHtml(plan,route){const updated=plan.eta_updated_at?notice(`ETA updated ${formatDate(plan.eta_updated_at)}. The stop times above are the current plan${plan.timing==='manual'?'':'; the driving-rules timeline below is from the original calculation'}.`):'';if(plan.timing==='manual')return `<div class="preview-box"><h3>Planned unloading · ${formatDate(plan.unloading_at)}</h3><div class="preview-grid"><div><span>Road distance</span><strong>${route.distance_km?km(route.distance_km):'Not entered'}</strong></div><div><span>Loading finishes</span><strong>${formatDate(plan.departure_at)}</strong></div><div><span>Available after unloading</span><strong>${formatDate(plan.available_at)}</strong></div><div><span>Total to availability</span><strong>${hours(plan.elapsed_hours)}</strong></div></div>${updated}${route.notices?.length?notice(route.notices.map(esc).join('<br>'),true):''}<details><summary>Stops & time on the road</summary>${timelineHtml(plan)}</details><p>Times entered by the dispatcher (from the driver). Driving and rest rules are not checked.</p></div>`;return `<div class="preview-box">${updated}<h3>Estimated unloading · ${formatDate(plan.unloading_at)}</h3><div class="preview-grid"><div><span>Road distance</span><strong>${km(route.distance_km)}</strong></div><div><span>Driving</span><strong>${hours(route.driving_hours)}</strong></div><div><span>Breaks & rest</span><strong>${hours(plan.rest_hours)}</strong></div><div><span>Road arrival</span><strong>${formatDate(plan.arrival_at)}</strong></div><div><span>Available after unloading</span><strong>${formatDate(plan.available_at)}</strong></div><div><span>Total to availability</span><strong>${hours(plan.elapsed_hours)}</strong></div></div>${route.notices?.length?notice(route.notices.map(esc).join('<br>'),true):''}<details><summary>Driving, breaks & handling timeline</summary>${timelineHtml(plan)}</details><p>Planning estimate with conservative single-driver rests. Availability does not guarantee remaining driving hours.</p></div>`;}
function timelineHtml(plan){return `<div class="timeline">${plan.timeline.map(e=>`<div class="timeline-row"><span>${esc(e.kind)} · ${hours(e.minutes/60)}</span><span>${formatDate(e.start)} → ${formatDate(e.end)}</span></div>`).join('')}</div>`;}
function stopTimeline(o){const next=nextStop(o),last=lastDoneStop(o),now=localParts(dispatchStamp(Date.now()));return `<div class="stop-timeline">${orderStops(o).map(s=>{const p=getLocation(s.location_id),done=s.status==='Done';let action='';if(o.status!=='Cancelled'){if(next?.seq===s.seq)action=`<label class="stop-when">Actual time<input type="datetime-local" data-stop-time value="${now}"></label><button class="btn small primary" data-action="confirm-stop" data-id="${o.id}" data-seq="${s.seq}">${confirmLabel(o,s)}</button>`;else if(done&&last?.seq===s.seq)action=`<button class="link-button" data-action="undo-stop" data-id="${o.id}" data-seq="${s.seq}">Undo confirmation</button>`;if(!done&&o.status!=='Completed')action+=`<details class="eta-edit"><summary>✎ Change ETA</summary><label>New arrival · from driver<input type="datetime-local" data-eta-time value="${localParts(s.planned_at)}"></label><button class="btn small" data-action="update-eta" data-id="${o.id}" data-seq="${s.seq}">Save ETA</button><small>Later stops move by the same amount.</small></details>`;}
  return `<div class="stop-item ${done?'done':''} ${next?.seq===s.seq?'next':''} ${stopIsLate(s)&&o.status!=='Cancelled'?'late':''}"><div class="stop-index">${done?'✓':s.seq}</div><div class="stop-body"><div class="stop-kind">${stopIcon[s.kind]} ${stopKindLabel(o,s)}${s.seq>1?` <span class="muted">· ${km(s.leg_km)} from previous stop</span>`:''}</div><strong>${esc(placeLabel(p))}</strong>${p?.address?`<small>${esc(p.address)}</small>`:''}${s.kind==='Trailer swap'?`<small class="stop-swap">Leave <b>${esc(s.drop_trailer||'no trailer')}</b> (marked Parked here) · take <b>${esc(s.pick_trailer)}</b></small>`:''}<div class="stop-times"><span>Planned ${formatDate(s.planned_at)}</span>${done?`<span class="done">Confirmed ${s.done_at?formatDate(s.done_at):''}</span>`:stopIsLate(s)&&o.status!=='Cancelled'?'<span class="late">Overdue</span>':''}</div></div><div class="stop-actions">${action}</div></div>`;}).join('')}</div>`;}
function orderDetail(id){const o=state.orders.find(x=>x.id===Number(id));if(!o)return;showModal(o.number,`<div class="detail-summary"><div><span>Tractor / trailer</span><strong>${esc(o.plate)} / ${esc(trailerChain(o))}</strong></div><div><span>Driver / carrier</span><strong>${esc(o.driver_name)}</strong><p>${esc(o.carrier)}</p></div><div><span>Operation / status</span>${badge(o.operation)} ${orderStatusBadge(o)}</div></div><h3 class="detail-title">Journey · ${orderStops(o).length} stops · counts as one trip</h3>${stopTimeline(o)}${previewHtml(o.plan,o.route_details)}${o.notes?`<div class="detail-grid"><div><h3>Dispatch notes</h3><p>${esc(o.notes)}</p></div></div>`:''}<p class="print-note">All times: Europe/Madrid dispatch clock. Estimated times require driver and location confirmation.</p><div class="form-actions"><button class="btn" data-action="print-order">Print order</button>${o.status==='Planned'?`<button class="btn" data-action="edit-order" data-id="${o.id}">Edit</button>`:''}${['Planned','In transit'].includes(o.status)?`<button class="btn danger" data-action="cancel-order" data-id="${o.id}">Cancel order</button>`:''}</div>`,'LOADING INSTRUCTIONS / DISPATCH COPY');}

document.addEventListener('click',async event=>{const nav=event.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;const form=button.closest('form');try{
  if(action==='close'){$('#modal').close();return;}
  if(action==='refresh-upcoming'){await refresh();return;}
  if(action==='upcoming-open-day'){selectedDay=button.dataset.date;period=1;filters.plate=state.trucks.find(t=>t.id===Number(button.dataset.truck))?.plate||'';filters.loading='';filters.unloading='';filters.operation='';filters.status='';navigate('planner');return;}
  if(action.startsWith('go-')){navigate(action.slice(3));return;}
  if(action==='nearby'){await openNearby({location_id:Number(id),context:button.dataset.context||'',radius_km:150,include_all:false});return;}
  if(action==='log-contact'){const slot=document.querySelector(`#modal [data-contact-slot="${id}"]`);if(slot){slot.innerHTML=contactForm(id);slot.querySelector('select').focus();return;}const p=getLocation(id);showModal('Log contact · '+(p?.company||''),`<p class="subtitle">${esc(placeLabel(p))}</p>${contactLines(p)}${contactForm(id)}`,'SAVED LOCATIONS / CONTACT');return;}
  if(action==='cancel-contact'){const slot=button.closest('[data-contact-slot]');if(slot)slot.innerHTML='';else $('#modal').close();return;}
  if(action==='edit-location'&&nearbyQuery&&button.closest('#nearby-results')){openMaster('locations',id,{nearby:nearbyQuery});return;}
  if(action==='new-order'){openOrder();return;}
  const masterActions={'new-trailer':['trailers',null],'edit-trailer':['trailers',id],'new-driver':['drivers',null],'new-truck':['trucks',null],'new-location':['locations',null],'edit-driver':['drivers',id],'edit-truck':['trucks',id],'edit-location':['locations',id]};
  if(masterActions[action]){openMaster(...masterActions[action]);return;}
  if(action==='archive-master'){openArchive(button.dataset.type,id);return;}
  if(action==='restore-master'){const type=button.dataset.type,record=state[type].find(x=>x.id===Number(id));if(!record||!window.confirm(`Restore ${record.plate}? It becomes active again in planning.`))return;button.disabled=true;const result=await api('/api/restore',{kind:type,id:record.id});await refresh();toast(`${result.restored} restored.`);return;}
  if(action==='prev-day'||action==='next-day'){selectedDay=addDays(selectedDay,(action==='next-day'?1:-1));render();return;}
  if(action==='today'){selectedDay=dayOf(state.now);render();return;}
  if(action==='clear-filters'){for(const key of Object.keys(filters))filters[key]='';render();return;}
  if(action==='order-detail'){orderDetail(id);return;}
  if(action==='edit-order'){const o=state.orders.find(x=>x.id===Number(id)),stops=orderStops(o),last=stops[stops.length-1];openOrder({...o,clock:o.clock_input,timing:o.plan?.end_state?'rules':'manual',unloading_arrive_at:last.planned_at,route_mode:o.route_source==='Manual'?'manual':'here',via:stops.slice(1,-1),distance_km:last.leg_km??o.distance_km,driving_hours:last.leg_hours??o.driving_hours});return;}
  if(action==='board-new-order'){const truck=state.trucks.find(t=>t.id===Number(id));openOrder({truck_id:truck.id,driver_id:truck.driver_id,trailer_id:truck.trailer_id,pickup_at:truckFreeFrom(truck.id,selectedDay+'T08:00')});await carryOrderClock($('#order-form'));return;}
  if(action==='add-via'){$('#via-stops').insertAdjacentHTML('beforeend',viaRow({kind:button.dataset.kind}));syncTiming();$('#order-preview').innerHTML='';$('#via-stops').lastElementChild.querySelector('select').focus();return;}
  if(action==='remove-via'){button.closest('[data-via]').remove();$('#order-preview').innerHTML='';return;}
  if(action==='confirm-stop'||action==='undo-stop'){const done=action==='confirm-stop',o=state.orders.find(x=>x.id===Number(id)),stop=orderStops(o).find(s=>s.seq===Number(button.dataset.seq));if(!done&&!window.confirm(`Undo the confirmation of ${stopKindLabel(o,stop).toLowerCase()} in ${getLocation(stop.location_id)?.city}?`))return;const when=button.parentElement.querySelector('[data-stop-time]')?.value;if(done){const at=when?new Date(when).getTime():Date.now(),early=(Date.parse(stop.planned_at)-at)/3600000;if(early>6&&!window.confirm(`${stopKindLabel(o,stop)} in ${getLocation(stop.location_id)?.city} is planned for ${formatDate(stop.planned_at)}, about ${Math.round(early)} hours later than the confirmation time. Confirm it as done anyway?`))return;}button.disabled=true;const inDetail=$('#modal').open&&!!button.closest('#modal');const result=await api('/api/stop-status',{order_id:o.id,seq:stop.seq,done,...(done&&when?{done_at:when}:{})});await refresh();if(inDetail)orderDetail(o.id);toast(result.message+(result.status==='Completed'?` ${o.number} is completed; the truck is free from the confirmed time.`:'')+(result.warning?' '+result.warning:''),!!result.warning);return;}
  if(action==='update-eta'){const when=button.parentElement.querySelector('[data-eta-time]')?.value;if(!when)throw new Error('Enter the new arrival time.');button.disabled=true;const result=await api('/api/stop-eta',{order_id:Number(id),seq:Number(button.dataset.seq),planned_at:when});await refresh();orderDetail(Number(id));toast(result.message+(result.warning?' '+result.warning:''));return;}
  if(action==='print-order'){window.print();return;}
  if(action==='reload-order'){const o=state.orders.find(x=>x.id===Number(id));const ready=new Date(o.available_at)>new Date(state.now)?o.available_at:state.now;openOrder({truck_id:o.truck_id,driver_id:o.driver_id,trailer_id:o.trailer_id,trailer:o.trailer,loading_id:o.unloading_id,pickup_at:ready,notes:'Next load after '+o.number});await carryOrderClock($('#order-form'));return;}
  if(action==='quick-location'){openMaster('locations',null,{draft:orderData(form),slot:button.dataset.slot});return;}
  if(action==='search-order-location'){button.disabled=true;const slot=button.dataset.slot;await searchOrderLocation(form,slot,$('#order-query-'+slot,form).value.trim());return;}
  if(action==='confirm-order-location'){button.disabled=true;await confirmOrderLocation(form,button.dataset.slot,Number(button.dataset.index));return;}
  if(action==='preview-order'){$('.form-error',form).textContent='';if(!validateSearchSelections(form))return;if(renderLoadingRestSuggestion(form)){$('#rest-suggestion').scrollIntoView({block:'nearest'});return;}button.disabled=true;if(!form.elements.loading_id.value||!form.elements.unloading_id.value)throw new Error('Choose both loading and unloading points before calculating the route.');if(!await ensureOrderCoordinates(form,true)){form.querySelector('.order-geo-box')?.scrollIntoView({block:'nearest'});return;}const data=orderData(form);const response=await api('/api/preview',data);$('#order-preview').innerHTML=previewHtml(response.plan,response.route);return;}
  if(action==='carry-clock'){button.disabled=true;await carryOrderClock(form);return;}
  if(action==='apply-rest-suggestion'){const suggestion=loadingRestSuggestion(orderData(form),form._restCreditFrom);if(!suggestion)return;form.elements.pickup_at.value=localParts(suggestion.pickup_at);for(const [key,value] of Object.entries(suggestion.clock))form.elements['clock_'+key].value=Number(value).toFixed(2);form.elements.clock_confirmed.checked=false;$('#order-preview').innerHTML='';$('.form-error',form).textContent='';$('#rest-suggestion').innerHTML=notice(`Proposed loading moved to <strong>${formatDate(suggestion.pickup_at)}</strong>, after ${suggestion.rest_hours} hours of assumed uninterrupted rest. Review the appointment and confirm actual rest with the driver before saving.`);$('#clock-message').textContent='Daily driving and duty reset after assumed qualifying rest; calendar-week driving totals are preserved.';return;}
  if(action==='cancel-order'){if(!window.confirm('Cancel this loading order? It will stay in history.'))return;await api('/api/order-status',{id:Number(id),status:'Cancelled'});$('#modal').close();await refresh();toast('Order cancelled.');return;}
  if(action==='geocode'){button.disabled=true;const values=formObject(form);const query=[values.address,values.postal_code,values.city,values.country].filter(Boolean).join(', ');const response=await api('/api/geocode',{query});const container=$('#geocode-results');container._matches=response.matches;container.innerHTML=response.matches.length?'<p class="subtitle">Confirm the correct address:</p>'+response.matches.map((m,i)=>`<button type="button" class="geo-option" data-action="choose-geocode" data-index="${i}">${esc(m.label)}<br>${m.lat}, ${m.lon} · ${esc(m.result_type)}</button>`).join(''):notice('No address matches. Refine the address or enter verified coordinates.',true);return;}
  if(action==='choose-geocode'){const selected=$('#geocode-results')._matches[Number(button.dataset.index)];form.elements.lat.value=selected.lat;form.elements.lon.value=selected.lon;form.elements.geo_label.value=selected.label;$('#geocode-results').innerHTML=notice('Selected: '+esc(selected.label));return;}
}catch(error){showError(form||$('#modal-content'),error);}finally{button.disabled=false;}});

function fillClock(response){const form=$('#order-form');for(const [key,value] of Object.entries(response.clock))form.elements['clock_'+key].value=Number(value).toFixed(2);$('#clock-message').textContent=response.message;$('details',form).open=true;$('#order-preview').innerHTML='';form._restCreditFrom=null;form._plannedClock=false;renderLoadingRestSuggestion(form);}
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(!validateSearchSelections(form))return;const button=$('[type=submit]',form);if(button)button.disabled=true;const error=$('.form-error',form);if(error)error.textContent='';try{
  if(form.getAttribute('id')==='master-form'){const data=formObject(form);if(data.id)data.id=Number(data.id);const result=await api('/api/'+form.dataset.type,data);const returnTo=form._returnTo;$('#modal').close();await refresh();if(returnTo?.nearby)await openNearby(returnTo.nearby);else if(returnTo)openOrder({...returnTo.draft,[returnTo.slot]:result.id});toast('Saved successfully.');}
  if(form.classList.contains('contact-form')){const data=formObject(form),inNearby=!!form.closest('#nearby-results');const result=await api('/api/location-contact',{location_id:Number(form.dataset.location),result:data.result,note:data.note||''});await refresh();if(inNearby&&nearbyQuery)await openNearby(nearbyQuery);else $('#modal').close();toast(result.message);}
  if(form.getAttribute('id')==='order-form'){if(renderLoadingRestSuggestion(form)){$('#rest-suggestion').scrollIntoView({block:'nearest'});return;}if(!await ensureOrderCoordinates(form,true)){form.querySelector('.order-geo-box')?.scrollIntoView({block:'nearest'});return;}const result=await api('/api/orders',orderData(form));$('#modal').close();await refresh();orderDetail(result.id);toast('Loading order saved. Every stop now appears in the daily planning and on the fleet board.');}
  if(form.getAttribute('id')==='archive-form'){const data=formObject(form);const result=await api('/api/archive',{kind:form.dataset.type,id:Number(form.dataset.id),reason:data.reason,note:data.note||''});$('#modal').close();await refresh();toast(`${result.archived} deleted (${data.reason}). History is kept; restore it from Show archived.`);}
}catch(error){showError(form,error);}finally{if(button)button.disabled=false;}});
document.addEventListener('change',event=>{const input=event.target;
  if(input.id==='show-archived'){showArchived=input.checked;render();return;}
  if((input.id==='nearby-radius'||input.id==='nearby-all')&&nearbyQuery){openNearby({...nearbyQuery,radius_km:Number($('#nearby-radius').value),include_all:$('#nearby-all').checked});return;}
  if(input.id==='upcoming-week'){weekOffset=Number(input.value);if(weekOffset===2)weekCount=1;loadUpcoming();return;}
  if(input.id==='upcoming-count'){weekCount=Number(input.value);loadUpcoming();return;}
  if(input.id==='upcoming-truck'){upcomingTruck=input.value;render();return;}
  if(input.id==='upcoming-operation'){upcomingOperation=input.value;render();return;}
  if(input.id==='planning-date'&&input.value){selectedDay=input.value;render();}
  if(input.dataset.filter){filters[input.dataset.filter]=input.value;render();}
  if(input.name==='truck_id'&&input.closest('#order-form')){const truck=state.trucks.find(t=>t.id===Number(input.value));if(truck){const form=$('#order-form');form.elements.driver_id.value=truck.driver_id||'';setSearchSelectValue(form,'trailer_id',truck.trailer_id);}}
  if(input.name==='route_mode')syncRouteMode();
  if(input.name==='timing'&&input.closest('#order-form'))syncTiming();
  if(['route_mode','loading_id','unloading_id'].includes(input.name)&&input.closest('#order-form')){const form=input.closest('#order-form');ensureOrderCoordinates(form,true).catch(error=>showError(form,error));}
  if(input.closest('#order-form')&&input.name!=='clock_confirmed'){const form=input.closest('#order-form');$('#order-preview').innerHTML='';if((input.name||'').startsWith('clock_')||input.name==='truck_id'){form._restCreditFrom=null;form._plannedClock=false;}if(['pickup_at','driver_id'].includes(input.name)&&form._plannedClock){carryOrderClock(form).catch(error=>showError(form,error));}else renderLoadingRestSuggestion(form);}
});
document.addEventListener('input',event=>{const input=event.target;if(input.dataset.filter){clearTimeout(filterTimer);const key=input.dataset.filter,value=input.value,start=input.selectionStart;filterTimer=setTimeout(()=>{filters[key]=value;render();const replacement=document.querySelector('[data-filter='+key+']');if(!replacement)return;replacement.focus();if(replacement.setSelectionRange)replacement.setSelectionRange(start,start);},250);}if(input.id==='directory-search'){const query=input.value.toLowerCase();for(const card of document.querySelectorAll('.directory-card'))card.hidden=!card.textContent.toLowerCase().includes(query);}});
// "+ Add new tractor" typed in an order: open the tractor form, then return to the draft order.
document.addEventListener('search-select-new',event=>{const form=event.target.closest('#order-form');if(!form||event.detail.name!=='truck_id')return;openMaster('trucks',null,{draft:orderData(form),slot:'truck_id',prefill:{plate:event.detail.value}});});
// Plain-text filters keep working as typed; these lists only recommend values.
suggestSources.plates=()=>[...state.trucks.map(t=>t.plate),...state.orders.map(o=>o.plate)];
suggestSources.places=()=>state.locations.flatMap(p=>[p.city,p.company,p.postal_code,placeLabel(p)]);
$('#close-modal').addEventListener('click',()=>$('#modal').close());
refresh().catch(error=>{$('#main').innerHTML=empty('Could not connect to the local server',esc(error.message));toast(error.message,true);});





